package jp.reader.manga;
import android.content.Context;import java.io.*;import java.util.concurrent.*;import java.util.*;
class Test{static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS "+s);}public static void main(String[] x)throws Exception{File dir=java.nio.file.Files.createTempDirectory("manga-cache-test").toFile();dir.mkdirs();Context ctx=new Context(dir);String url="https://example.com/a.zip";byte[] bytes=new byte[20000];new Random(3).nextBytes(bytes);CountDownLatch l=new CountDownLatch(1);DownloadCache.start(ctx,new Dav(bytes),url,msg->{System.out.println(msg);l.countDown();});ok(l.await(5,TimeUnit.SECONDS),"background completion");File f=DownloadCache.available(ctx,url);ok(f!=null&&Arrays.equals(bytes,java.nio.file.Files.readAllBytes(f.toPath())),"download persisted identical");long old=System.currentTimeMillis()-31L*24*60*60*1000;f.setLastModified(old);DownloadCache.pin(url);DownloadCache.cleanup(ctx);ok(DownloadCache.available(ctx,url)!=null,"読書中の期限切れキャッシュを保護");DownloadCache.pin(null);ok(DownloadCache.available(ctx,url)==null&&!f.exists(),"expiry after 30 days");CountDownLatch l2=new CountDownLatch(1);DownloadCache.start(ctx,new Dav(bytes),url,msg->l2.countDown());ok(l2.await(5,TimeUnit.SECONDS),"second download");File accessed=DownloadCache.available(ctx,url);long savedAt=accessed.lastModified();DownloadCache.touch(ctx,url);ok(accessed.lastModified()==savedAt&&CachePolicy.accessFile(accessed).exists(),"アクセス記録は30日期限の保存時刻を変えない");ok(DownloadCache.delete(ctx,url),"saved file deletion reports success");ok(DownloadCache.available(ctx,url)==null,"delete on completion");ok(DownloadCache.delete(ctx,url),"missing cache deletion succeeds");
  Dav owner=new Dav(bytes);owner.entered=new CountDownLatch(1);owner.release=new CountDownLatch(1);CountDownLatch completed=new CountDownLatch(1);
  DownloadCache.start(ctx,owner,url,msg->completed.countDown());ok(owner.entered.await(5,TimeUnit.SECONDS),"download opened");
  owner.close();ok(owner.ownerCount()==1,"download retains connection after reader closes");
  owner.release.countDown();ok(completed.await(5,TimeUnit.SECONDS),"retained download completed");ok(owner.ownerCount()==0,"download releases final connection owner");
  String url2="https://example.com/slow.zip";Dav slow=new Dav(bytes);slow.entered=new CountDownLatch(1);slow.release=new CountDownLatch(1);slow.closeEntered=new CountDownLatch(1);slow.closeRelease=new CountDownLatch(1);slow.onZero=new CountDownLatch(1);
  DownloadCache.start(ctx,slow,url2,msg->{});ok(slow.entered.await(5,TimeUnit.SECONDS),"slow download started");slow.close();
  ExecutorService caller=Executors.newSingleThreadExecutor();Future<Boolean> deleted=caller.submit(()->DownloadCache.delete(ctx,url2));
  try{ok(deleted.get(2,TimeUnit.SECONDS),"delete returns before slow connection close");ok(slow.closeEntered.await(2,TimeUnit.SECONDS),"connection close started asynchronously");}finally{slow.closeRelease.countDown();slow.release.countDown();caller.shutdownNow();}
  ok(slow.onZero.await(5,TimeUnit.SECONDS),"cancelled download releases retained client");ok(DownloadCache.available(ctx,url2)==null,"cancelled download does not persist");System.exit(0);}}
